<?php
require __DIR__ . '/config.php';
$pdo = db();
$page = (string)($_GET['page'] ?? 'home');
$user = current_user();
$categories = ['Romance','Terror','Fantasia','Ficção científica','Mistério','Aventura','Suspense','Drama','História','Biografia','Autoajuda','Psicologia','Literatura','Infantil','Outro'];

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $action = (string)($_POST['action'] ?? '');
    try {
        if ($action === 'register') {
            $name=post_string('name',100); $email=strtolower(post_string('email',190)); $pass=(string)($_POST['password']??''); $city=post_string('city',100);
            if ($name==='' || !filter_var($email,FILTER_VALIDATE_EMAIL) || strlen($pass)<8) throw new RuntimeException('Preencha os campos corretamente. A senha precisa ter pelo menos 8 caracteres.');
            $q=$pdo->prepare('INSERT INTO users(name,email,password_hash,city) VALUES(?,?,?,?)');
            $q->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT),$city]);
            session_regenerate_id(true); $_SESSION['user']=['id'=>(int)$pdo->lastInsertId(),'name'=>$name,'email'=>$email,'city'=>$city];
            flash('Conta criada! Boas leituras.'); go('home');
        }
        if ($action === 'login') {
            $email=strtolower(post_string('email',190)); $pass=(string)($_POST['password']??'');
            $q=$pdo->prepare('SELECT * FROM users WHERE email=?'); $q->execute([$email]); $u=$q->fetch();
            if (!$u || !password_verify($pass,$u['password_hash'])) throw new RuntimeException('E-mail ou senha incorretos.');
            session_regenerate_id(true); $_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['name'],'email'=>$u['email'],'city'=>$u['city']];
            go('home');
        }
        if ($action === 'logout') { $_SESSION=[]; session_destroy(); header('Location: index.php'); exit; }
        require_login(); $uid=(int)$user['id'];
        if ($action === 'add_book') {
            $title=post_string('title',200); $author=post_string('author',150); $desc=post_string('description',5000);
            $cat=post_string('category',80); $qty=(int)($_POST['quantity']??1); $city=post_string('city',100);
            if ($title===''||$author===''||$desc===''||$city===''||!in_array($cat,$categories,true)||$qty<1||$qty>500) throw new RuntimeException('Confira os dados do livro. A quantidade deve ser de 1 a 500.');
            $q=$pdo->prepare('INSERT INTO books(title,author,description,category,quantity,owner_id,city) VALUES(?,?,?,?,?,?,?)');
            $q->execute([$title,$author,$desc,$cat,$qty,$uid,$city]); flash('Livro adicionado ao catálogo!'); go('explore');
        }
        if ($action === 'wishlist') {
            $bid=(int)($_POST['book_id']??0); if(!book_by_id($bid)) throw new RuntimeException('Livro não encontrado.');
            $q=$pdo->prepare('SELECT 1 FROM wishlist WHERE user_id=? AND book_id=?'); $q->execute([$uid,$bid]);
            if($q->fetchColumn()) { $pdo->prepare('DELETE FROM wishlist WHERE user_id=? AND book_id=?')->execute([$uid,$bid]); flash('Livro removido da lista de desejos.'); }
            else { $pdo->prepare('INSERT INTO wishlist(user_id,book_id) VALUES(?,?)')->execute([$uid,$bid]); flash('Livro salvo na lista de desejos.'); }
            go((string)($_POST['return_page']??'explore'));
        }
        if ($action === 'borrow') {
            $bid=(int)($_POST['book_id']??0); $days=(int)($_POST['days']??14); $b=book_by_id($bid);
            if(!$b) throw new RuntimeException('Livro não encontrado.');
            if((int)$b['owner_id']===$uid) throw new RuntimeException('Você não pode pegar emprestado um livro que você mesmo cadastrou.');
            if(!in_array($days,[7,14,30],true)) throw new RuntimeException('Prazo inválido.');
            $q=$pdo->prepare("SELECT COUNT(*) FROM loans WHERE book_id=? AND status='active'"); $q->execute([$bid]);
            if((int)$q->fetchColumn()>=$b['quantity']) throw new RuntimeException('Não há cópias disponíveis no momento.');
            $q=$pdo->prepare("SELECT COUNT(*) FROM loans WHERE borrower_id=? AND status='active'"); $q->execute([$uid]);
            if((int)$q->fetchColumn()>=10) throw new RuntimeException('Você já tem 10 empréstimos ativos. Devolva um livro antes de pegar outro.');
            $q=$pdo->prepare("INSERT INTO loans(book_id,borrower_id,owner_id,borrowed_at,due_date) VALUES(?,?,?,?,DATE_ADD(CURDATE(), INTERVAL ? DAY))");
            $q->execute([$bid,$uid,$b['owner_id'],date('Y-m-d'),$days]); flash('Empréstimo registrado. Combine a retirada/devolução com quem cadastrou o livro.'); go('loans');
        }
        if ($action === 'return_book') {
            $lid=(int)($_POST['loan_id']??0);
            $q=$pdo->prepare("UPDATE loans SET status='returned', returned_at=CURDATE() WHERE id=? AND borrower_id=? AND status='active'");
            $q->execute([$lid,$uid]); if(!$q->rowCount()) throw new RuntimeException('Empréstimo não encontrado ou já devolvido.');
            flash('Devolução registrada. Combine a entrega física com o dono do livro.'); go('loans');
        }
        if ($action === 'book_review') {
            $bid=(int)($_POST['book_id']??0); $rating=(int)($_POST['rating']??0); $review=post_string('review',2000);
            if(!book_by_id($bid)||$rating<1||$rating>5||$review==='') throw new RuntimeException('Informe uma nota de 1 a 5 e escreva sua avaliação.');
            $q=$pdo->prepare('INSERT INTO book_reviews(user_id,book_id,rating,review) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE rating=VALUES(rating), review=VALUES(review), created_at=CURRENT_TIMESTAMP');
            $q->execute([$uid,$bid,$rating,$review]); flash('Avaliação salva!'); go('reviews&book='.$bid);
        }
        if ($action === 'recommend') {
            $bid=(int)($_POST['book_id']??0); $msg=post_string('message',600);
            if(!book_by_id($bid)||$msg==='') throw new RuntimeException('Escolha um livro e escreva por que recomenda.');
            $q=$pdo->prepare('INSERT INTO recommendations(user_id,book_id,message) VALUES(?,?,?) ON DUPLICATE KEY UPDATE message=VALUES(message),created_at=CURRENT_TIMESTAMP');
            $q->execute([$uid,$bid,$msg]); flash('Recomendação publicada!'); go('recommendations');
        }
        if ($action === 'chat') {
            $msg=post_string('message',1200); if($msg==='') throw new RuntimeException('Escreva uma mensagem antes de enviar.');
            $pdo->prepare('INSERT INTO chat_messages(user_id,message) VALUES(?,?)')->execute([$uid,$msg]); go('club');
        }
        if ($action === 'site_review') {
            $rating=(int)($_POST['rating']??0); $comment=post_string('comment',2000);
            if($rating<1||$rating>5||$comment==='') throw new RuntimeException('Dê uma nota de 1 a 5 e conte como foi sua experiência.');
            $pdo->prepare('INSERT INTO site_reviews(user_id,rating,comment) VALUES(?,?,?) ON DUPLICATE KEY UPDATE rating=VALUES(rating),comment=VALUES(comment),created_at=CURRENT_TIMESTAMP')->execute([$uid,$rating,$comment]);
            flash('Avaliação do site registrada!'); go('site-rating');
        }
    } catch (PDOException $e) {
        if ((string)$e->getCode()==='23000') flash('Esse registro já existe ou algum dado está duplicado.','error');
        else { error_log($e->getMessage()); flash('Não foi possível concluir a operação. Confira a conexão e tente novamente.','error'); }
        go($page);
    } catch (RuntimeException $e) { flash($e->getMessage(),'error'); go($page); }
}

function book_cards(array $books, string $returnPage='explore'): void {
    global $pdo,$user;
    if(!$books){echo '<div class="empty">Nenhum livro encontrado com esses filtros.</div>';return;}
    foreach($books as $b){
        $q=$pdo->prepare("SELECT COUNT(*) FROM loans WHERE book_id=? AND status='active'"); $q->execute([$b['id']]);
        $available=max(0,(int)$b['quantity']-(int)$q->fetchColumn());
        $avg=average_rating((int)$b['id']);
        $saved=false;
        if($user){$q=$pdo->prepare('SELECT 1 FROM wishlist WHERE user_id=? AND book_id=?');$q->execute([$user['id'],$b['id']]);$saved=(bool)$q->fetchColumn();}
        echo '<article class="book-card"><div class="book-cover"><span>'.h($b['category']).'</span><strong>'.h($b['title']).'</strong><small>'.h($b['author']).'</small></div><div class="book-info"><h3>'.h($b['title']).'</h3><p class="muted">por '.h($b['author']).'</p><p class="desc">'.h($b['description']).'</p><p class="muted">📍 '.h($b['city']).' · ⭐ '.number_format($avg,1,',','.').'/5</p><p class="'.($available?'available':'unavailable').'">'.($available?'● '.$available.' cópia(s) disponível(is)':'● Sem cópias disponíveis').'</p><div class="button-row"><a class="btn light" href="index.php?page=reviews&book='.(int)$b['id'].'">Avaliações</a>';
        if($user){
            echo '<form method="post">'.csrf_field().'<input type="hidden" name="action" value="wishlist"><input type="hidden" name="book_id" value="'.(int)$b['id'].'"><input type="hidden" name="return_page" value="'.h($returnPage).'"><button class="btn heart" title="Lista de desejos">'.($saved?'♥ Salvo':'♡ Desejar').'</button></form>';
            if($available && (int)$b['owner_id']!==(int)$user['id']) echo '<form method="post">'.csrf_field().'<input type="hidden" name="action" value="borrow"><input type="hidden" name="book_id" value="'.(int)$b['id'].'"><input type="hidden" name="days" value="14"><button class="btn">Pegar emprestado</button></form>';
        } else echo '<a class="btn" href="index.php?page=login">Entrar para pegar</a>';
        echo '</div></div></article>';
    }
}
function page_title(string $page): string {
    return ['home'=>'Início','explore'=>'Explorar livros','loans'=>'Meus empréstimos','wishlist'=>'Lista de desejos','club'=>'Clube de leitura','recommendations'=>'Recomendações','reviews'=>'Avaliações dos livros','add-book'=>'Adicionar livro','site-rating'=>'Avaliação do site','settings'=>'Minha conta','login'=>'Entrar','register'=>'Criar conta'][$page] ?? 'Biblioteca Virtual';
}
$validPages=['home','explore','loans','wishlist','club','recommendations','reviews','add-book','site-rating','settings','login','register'];
if(!in_array($page,$validPages,true)) $page='home';
if(in_array($page,['loans','wishlist','club','recommendations','reviews','add-book','site-rating','settings']) && !$user){flash('Entre na sua conta para acessar essa área.','error');go('login');}
$search=trim((string)($_GET['q']??'')); $cat=trim((string)($_GET['category']??''));
