<div class="card"><div class="card-head"><h2>Meus empréstimos</h2><a href="index.php?page=explore">Encontrar livros →</a></div><?php if(!$loans):?><div class="empty">Você ainda não pegou livros emprestados.</div><?php else:?><div class="table-wrap"><table class="table"><thead><tr><th>Livro</th><th>Disponibilizado por</th><th>Devolução</th><th>Prazo</th><th>Status / ação</th></tr></thead><tbody><?php foreach($loans as $l):$days=(int)floor((strtotime($l['due_date'])-strtotime(date('Y-m-d')))/86400);?><tr><td><b><?=h($l['title'])?></b><br><span class="muted"><?=h($l['author'])?></span></td><td><?=h($l['owner_name'])?><br><span class="muted"><?=h($l['city'])?></span></td><td><?=date('d/m/Y',strtotime($l['due_date']))?></td><td><?php if($l['status']==='returned'):?><span class="pill">Devolvido</span><?php elseif($days<0):?><span class="pill warn">Atrasado <?=abs($days)?> dia(s)</span><?php else:?><span class="pill"><?=$days?> dia(s) restante(s)</span><?php endif;?></td><td><?php if($l['status']==='active'):?><form method="post" onsubmit="return confirm('Registrar a devolução deste livro? Combine a entrega com o dono.');"><?=csrf_field()?><input type="hidden" name="action" value="return_book"><input type="hidden" name="loan_id" value="<?=$l['id']?>"><button class="btn light">Devolver antes</button></form><?php else:?>Concluído<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><div class="notice">O site registra o prazo, mas não faz entrega física. Combine a devolução com o responsável pelo livro.</div></div>
