<div class="card"><div class="card-head"><h2>✦ Recomendações da comunidade</h2></div><form method="post" class="form-grid"><?=csrf_field()?><input type="hidden" name="action" value="recommend"><div class="field"><label>Livro</label><select name="book_id" required><option value="">Escolha um livro</option><?php foreach($books as $b):?><option value="<?=$b['id']?>"><?=h($b['title'].' — '.$b['author'])?></option><?php endforeach;?></select></div><div class="field"><label>Por que recomenda?</label><input class="input" name="message" required maxlength="600" placeholder="Ex.: leitura envolvente e personagens marcantes"></div><div class="field full"><button class="btn">Publicar recomendação</button></div></form></div><div class="card"><div class="card-head"><h2>O que estão recomendando</h2></div><?php if(!$recs):?><div class="empty">Ainda não há recomendações.</div><?php else:foreach($recs as $r):?><div class="review"><b><?=h($r['title'])?></b> <span class="muted">por <?=h($r['author'])?></span><p><?=h($r['message'])?></p><span class="muted">Recomendado por <?=h($r['name'])?> · <?=date('d/m/Y',strtotime($r['created_at']))?></span></div><?php endforeach;endif;?></div>
